//! Transactional cache-group certificate layer.
//!
//! This module implements the committed-state certificates and the exact
//! proposal violation counts described in PROTOCOL.md.  The committed state is
//! kept in a set of flat arrays together with incrementally maintained
//! derived quantities (per-group footprints, per-node reservations, group
//! loads, distinct (domain, class) pair counts and the four violation
//! counters).  A transaction is applied directly on top of the committed
//! state while a journal of the previous field values is recorded; a rejected
//! proposal is rolled back by replaying that journal in reverse order, which
//! restores every committed value exactly.

use crate::solver::SolverProblem;
use std::collections::HashMap;

const NONE: usize = usize::MAX;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize),
    Weight(usize, u64),
    Class(usize, u64),
    Bind(usize, usize),
    Pin(usize, bool),
    Quota(usize, u64),
    Budget(usize, u64),
    Cap(usize, u64),
}

#[derive(Clone, Default)]
pub struct Query {
    pub groups: Vec<usize>,
    pub nodes: Vec<usize>,
    pub tasks: Vec<usize>,
}

pub struct Certificate {
    pub totals: [u64; 4],
    pub groups: Vec<[i64; 8]>,
    pub nodes: Vec<[u64; 3]>,
    pub tasks: Vec<[u64; 6]>,
}

pub struct Outcome {
    pub accepted: bool,
    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

#[derive(Clone, Copy)]
struct Snap {
    group: usize,
    tpl: usize,
    weight: u64,
    class: u64,
    pin: bool,
}

pub struct Ledger {
    // sizes
    n: usize,
    words: usize,
    tcount: usize,
    gcount: usize,

    // static template data
    tpl_domain: Vec<u64>,
    tpl_words: Vec<u64>,

    // task state
    t_group: Vec<usize>,
    t_tpl: Vec<usize>,
    t_weight: Vec<u64>,
    t_class: Vec<u64>,
    t_pin: Vec<bool>,
    t_prev: Vec<usize>,
    t_next: Vec<usize>,

    // group / node state
    quota: Vec<u64>,
    budget: Vec<u64>,
    cap: Vec<u64>,

    // group derived state
    g_members: Vec<u32>,
    g_load: Vec<u64>,
    g_fp_size: Vec<u32>,
    g_ref: Vec<u32>,
    g_head: Vec<usize>,
    g_pin: Vec<u32>,
    g_distinct: Vec<u32>,
    pairs: HashMap<(usize, u64, u64), u32>,

    // node derived state
    usage: Vec<u64>,

    // global counters
    total_slots: u64,
    total_weight: u64,
    pinned_total: u32,
    active: usize,
    over_cap: usize,
    mixed: usize,
    work_bad: usize,
    revision: u64,

    // transaction scratch space
    tx_id: u32,
    tx_stamp: Vec<u32>,
    tx_snap: Vec<Snap>,
